  fundo: {"nome": "labirinto-salgado.jpg", "url": "/mapas/fa/labirinto-salgado.jpg", "escala": 100, "x0": 0, "y0": 0, "giro": 0, "opacidade": 1},
  interativos: [
    {"x": 30, "y": 70, "id": "rastrosDaEntrada", "rotulo": "Olhar o chão", "texto": "O chão de carne guarda marcas, mas se fecha devagar sobre elas, como pele.", "pista": {"verbo": "percepcao", "cd": 15, "achado": "Muitas criaturas saíram daqui para a esquerda, umas arrastadas: o bando dos fanáticos, com os presos. Mais tarde, três pares de botas foram para a direita."}, "olhar": true},
    {"x": 14, "y": 58, "id": "duergarMortos", "rotulo": "Olhar os corpos", "texto": "Quatro anões de pele cinzenta, de armadura, mortos de arma há meses.", "pista": {"verbo": "investigar", "cd": 12, "achado": "Todos têm a cabeça aberta, e a ferida é de depois da morte: alguma coisa vem roer."}, "olhar": true},
    {"x": 52, "y": 55, "id": "muroDaSoberba", "rotulo": "Olhar a parede curva", "texto": "Cinco corpos fundidos na parede até o peito, de boca aberta num grito parado. Restos de mantos de mago."},
    {"x": 38, "y": 58, "id": "tumorPregado", "rotulo": "Olhar a bola pregada", "texto": "Uma bola de vísceras do tamanho de um escudo, pregada na parede por uma espada grande de lâmina prateada e serrilhada. Embaixo, uma poça de gosma."},
    {"x": 57, "y": 51, "id": "sombrasQueDancam", "rotulo": "Olhar o nicho", "texto": "No escuro de um nicho, sombras dançam sem corpo, no ritmo de uma flauta que ninguém está tocando."},
    {"x": 48, "y": 46, "id": "bauDosGithyanki", "rotulo": "Olhar o acampamento", "texto": "Três sacos de dormir em volta de um baú, e dois bastões de metal de dois palmos saindo da parede do fundo."},
    {"x": 59, "y": 37, "id": "barrileteDoShalfi", "rotulo": "Olhar o nicho", "texto": "Um saco de dormir imundo e um barrilete. Ninguém dorme aqui há dias."},
    {"x": 54, "y": 23, "id": "buracoDoShalfi", "rotulo": "Olhar a cova", "texto": "Uma cova rasa num canto, de borda preta como carne morta."},
    {"x": 5, "y": 49, "id": "livroDoJomlus", "rotulo": "Olhar o livro", "texto": "Um livro enorme aberto sobre um calombo de carne, de letras que parecem se mexer."},
    {"x": 4, "y": 30, "id": "rasgoDosFlumphs", "rotulo": "Olhar a parede do fundo", "texto": "Um rasgo estreito na parede, por onde se vê um caleidoscópio de cores que doem. Bolhas sobem de nódulos na carne e estouram no ar."},
    {"x": 27, "y": 49, "id": "restosDeRefeicao", "rotulo": "Olhar os restos", "texto": "Ossos e pedaços de carne, e farrapos de mantos de culto. Alguém morreu tentando abrir a porta enorme ao lado."},
    {"x": 39, "y": 30, "id": "lonaDeB15", "rotulo": "Olhar a lona", "texto": "Uma lona rasgada pende do teto e esconde um quadrado no meio da sala. De dentro vem um assobio fino de arame esticado, que dá dor de cabeça."},
    {"x": 50, "y": 18, "id": "buracoDeB16", "rotulo": "Olhar atrás da bancada", "texto": "Atrás da bancada tombada, um buraco de dois metros no chão. Uma corda com nós, amarrada no pé da bancada, desce para o escuro."},
    {"x": 42, "y": 10, "id": "bauDosColecionadores", "rotulo": "Olhar o nicho", "texto": "Dois catres e um baú pequeno. Dentro, ferramentas que não servem: sovelas cegas, um martelo de cabeça presa por corrente, réguas de marcas erradas."},
    {"x": 24, "y": 34, "id": "bibliotecariosMortos", "rotulo": "Olhar os corpos", "texto": "Três devoradores de mentes mortos no icor escuro, como se tivessem brigado entre si. Nas paredes, dezenas de cristais embutidos.", "pista": {"verbo": "investigar", "cd": 14, "achado": "Foi encenado: furos de tridente e cortes de machado grande, e nenhuma das armas está aqui."}, "olhar": true},
    {"x": 19, "y": 21, "id": "cicatriz", "rotulo": "Olhar a parede", "texto": "A parede do nicho tem nós como cicatriz.", "pista": {"verbo": "investigar", "cd": 12, "achado": "Alguém cortou um ponto mole aqui, até o outro lado, e a carne se fechou. Não se corta de novo."}, "olhar": true},
    {"x": 14, "y": 16, "id": "escrivaninhaDaAshripask", "rotulo": "Olhar o nicho", "texto": "Um catre dobrável com peles e uma escrivaninha portátil, e dois bastões cônicos saindo do chão, um de cada lado, a seis metros um do outro."},
    {"x": 31, "y": 11, "id": "bastoesDaPoca", "rotulo": "Olhar a poça", "texto": "Uma poça de uns 18 m, de luz verde fraca lá no fundo, e grumos de carne boiando. Na beira, dois bastões cônicos quase se tocando."},
  ],
  embacado: [{"x": 29, "y": 58}, {"x": 30, "y": 58}, {"x": 31, "y": 58}, {"x": 32, "y": 58}, {"x": 29, "y": 59}, {"x": 30, "y": 59}, {"x": 31, "y": 59}, {"x": 32, "y": 59}, {"x": 29, "y": 60}, {"x": 30, "y": 60}, {"x": 31, "y": 60}, {"x": 32, "y": 60}, {"x": 29, "y": 61}, {"x": 30, "y": 61}, {"x": 31, "y": 61}, {"x": 32, "y": 61}, {"x": 29, "y": 62}, {"x": 30, "y": 62}, {"x": 31, "y": 62}, {"x": 32, "y": 62}, {"x": 29, "y": 63}, {"x": 30, "y": 63}, {"x": 31, "y": 63}, {"x": 32, "y": 63}, {"x": 29, "y": 64}, {"x": 30, "y": 64}, {"x": 31, "y": 64}, {"x": 32, "y": 64}, {"x": 29, "y": 65}, {"x": 30, "y": 65}, {"x": 31, "y": 65}, {"x": 32, "y": 65}, {"x": 29, "y": 66}, {"x": 30, "y": 66}, {"x": 31, "y": 66}, {"x": 32, "y": 66}, {"x": 29, "y": 67}, {"x": 30, "y": 67}, {"x": 31, "y": 67}, {"x": 32, "y": 67}, {"x": 29, "y": 68}, {"x": 30, "y": 68}, {"x": 31, "y": 68}, {"x": 32, "y": 68}],
